(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["mi"] = {"ui":{"skip":"Peke ki ngā ihirangi","back":"← Hoki ki AI-gile","lang.button":"Reo: {name}","lang.dialog":"Kōwhiria he reo","lang.search":"Rapua ngā reo","lang.none":"Kāore he reo e ōrite","lang.notYet":"Kāore anō kia whakamāoritia ki te reo {name}","theme.aria":"Whakawhiti āhua: mārama, pōuri, pango rānei","theme.toLight":"Whakawhiti ki te āhua mārama","theme.toDark":"Whakawhiti ki te āhua pōuri","theme.toBlack":"Whakawhiti ki te āhua pango (pango tūturu, pai mō ngā mata OLED)","words.underline":"Tāroatia ēnei kupu i te whārangi","words.underlineHelp":"Whakanohoia te pere ki runga, pātōtia rānei tētahi kupu he rārangi ira tōna, kia kite ai koe i tōna tikanga.","words.col.todo":"Ngā kāri kua tīpakohia mō nāianei: ka tīmata te rōpū i ēnei i muri ake.","words.col.doing":"Kei te mahi tētahi AI i tēnei kāri i tēnei wā tonu.","words.col.review":"Kua oti i tētahi AI te mahi; ka arotake tētahi atu i mua i tana tae atu ki a koe.","words.col.verify":"E tatari ana ki a koe: whakamātauria, ka kī mai mehemea e mahi ana.","words.col.team":"Ō tuhipoka, ō whakautu rānei, e tatari ana kia tikina e te rōpū.","words.col.done":"Kua oti, kua whakaaetia hoki.","index.title":"AI-gile: tō rōpū hanga AI i runga i te papa kotahi","index.description":"He papa kanban a AI-gile mō ngā rōpū waehere AI. Ka mahi rātou i a koe e moe ana; ka toe māu he puranga poto: he mea hei whakatau, hei whakamātau, hei whakaae.","hero.logoAlt":"Tohu papa AI-gile","hero.h1.html":"Tō rōpū hanga AI, i runga i te papa&nbsp;kotahi.","hero.alpha":"🐣 Pre-alpha kati","hero.alphaTitle":"Tōmua, kāore anō kia oti: ngā mihi mō tō whakamātau!","hero.lede":"Ka hanga rātou i a koe e moe ana. Ka ara koe ki te puranga poto kotahi: ētahi pātai, ētahi mea hei whakamātau, tētahi taimana waiporoporo e rua rānei. Pāwhiri, whakaae, hoki ki tō kawhe.","dl.windows":"Taupānga Windows","dl.browser":"Whakahaerehia i tō pūtirotiro","dl.messenger":"📱 Messenger mō tō waea","dl.soon":"Tērā ake nei","dl.notify":"🔔 Whakamōhio mai ina tuwhera","dl.notifySmall":"Alpha, beta rānei","hero.secondary":"Agile, engari kāore te rōpū e hiahia ana ki te kawhe tū. (Heoi ka mahi tonu rātou i ngā stand-up.)","pitch.h2":"AI-gile i te maha o ngā kupu e hiahia ana koe","pitch.lede":"Kōwhiria te roa, mai i te kupu kotahi ki te 144. He whakaahuatanga motuhake ia roa, i tuhia mō taua rahi. Toia te kaiwhakahaere, whakamahia rānei ngā pātuhi pere.","pitch.rangeLabel":"Te roa i ngā kupu","pitch.dice":"🎲 tētahi atu putanga","pitch.words.one":"{n} kupu","pitch.words.other":"{n} kupu","pitch.letters.one":"{n} reta","pitch.letters.other":"{n} reta","pitch.chars.one":"{n} tohu","pitch.chars.other":"{n} tohu","count.line.html.one":"E {n} ngā kāri kei te papa i tēnei wā","count.line.html.other":"E {n} ngā kāri kei te papa i tēnei wā","people.humans.html.one":"👥 {n} tangata","people.humans.html.other":"👥 {n} tāngata","people.agents.html.one":"🤖 {n} kaiāwhina AI","people.agents.html.other":"🤖 {n} kaiāwhina AI","people.working.html.one":"⚡ {n} e mahi ana ināianei","people.working.html.other":"⚡ {n} e mahi ana ināianei","pre.title":"AI-gile: he mea e hangaia ana","pre.description":"He mea e hangaia ana i konei: he papa e hanga ai ngā rōpū AI i āu e tono ai, ā, ka ako i a koe i te haere tonu. He pre-alpha kati me ngā hoa i tēnei wā.","pre.h1":"He mea e hangaia ana i konei. 🤫","pre.line":"He papa e hanga ai ngā rōpū AI i āu e tono ai, ā, ka ako i a koe i te haere tonu. He pre-alpha kati me ngā hoa i tēnei wā.","pre.btn":"🔔 Whakamōhio mai ina tuwhera","pre.peek":"Kei muri i te karaehe: te papa tūturu, ora. He pae tae ia kāri.","pre.peekFake":"Kei muri i te karaehe: te āhua o tētahi papa e mahi ana.","pre.night":"🌙 Ko te kaitiaki o te pō te kaiwhakahaere · 😴 e okioki ana te tangata","features.aria":"Āna mahi","f.pile.h":"Te puranga kotahi mōu","f.pile.html":"<b>Māu</b> kei konei ngā mea katoa e tatari ana ki a koe, puta noa i ngā kaupapa katoa: ngā pātai, ngā mea hei whakamātau, ngā mahi mā te tangata anake. Ka mea tō rārangi he aha te mea e whai ake nei, me te roa e pau ai.","f.sleep.h":"Ngā rōpū e mahi ana i a koe e moe ana","f.sleep.p":"He kaihautū me tētahi rōpū kaiwhakahaere AI tō ia kaupapa. Tāpiritia he kōrero ki tētahi kāri, ka oho te rōpū, ka mahi, ka hoatu anō me ngā hikoi e ngāwari ana mā te tangata ngenge.","f.tester.h":"Ka tirotiro tuatahi he kaiwhakamātau AI","f.tester.p":"I mua i te taenga ki a koe, ka whai te kaiwhakamātau i ngā hikoi i runga i tētahi kape o te taupānga, ka whakaatu i tāna i kite ai, me te tānga mata. Tirohia wawe ngā mea i ngata, ka whakaae mā te pāwhiri kotahi.","f.proof.h":"He taunakitanga, ehara i te oati","f.proof.p":"Ka whakaatu ia tuku i ngā mea kua rerekē: ngā kōnae, te rerekētanga, ngā tānga mata. Kāore e tika kia whakatuwheratia ia taupānga hei tiro mēnā kua oti.","f.chat.h":"Kōrero ki ō kaihautū","f.chat.p":"He kōrero-ara pērā i a Discord: kotahi te tohu mō ia kaupapa, he taimana waiporoporo mō ngā mea e hiahia ana ki a koe. Tukuna he whakaaro ki tētahi kaihautū; ka huri ia hei kāri me tētahi mahere, me tētahi pātene ✅ Haere.","f.tidy.h":"Ka noho ia i te tōtika","f.tidy.p":"Ka whakakotahi ngā kāri e hāngai ana, ka whakatikahia ngā taitara rangirua, ā, ka tiaki te tirotiro tohu i te waehere kia kōmaki. Torutoru ake ngā mea hei huri atu ki, torutoru ake ngā mea hei whakaaro.","f.private.h":"Nōu, i runga i tō rorohiko","f.private.li1":"Ka rere te papa i runga i tō ake rorohiko, ā, ko koe anake tāna e whakautu ai.","f.private.li2":"He hunahuna ngā karere tūmataiti i waenga i ngā tāngata, mai i tētahi pito ki tētahi.","f.private.li3":"Kāore he kāute, kāore he kaiwhai, kāore he pihikete.","f.lang.h":"I tō reo","f.lang.p":"Neke atu i te 120 ngā reo, mai i te Tati, te Wēra me te Hapani ki te kaipahua, ki a Yoda me te Klingon, me tētahi whakawhiti tere ki te reo Ingarihi mō ngā kupu ngaio.","f.service.h":"Mai i tētahi whakaaro ki tētahi ratonga tūturu","f.service.p":"Kua hanga koe i tētahi mea me te AI e whakamahia ana e te tangata ināianei? Tohua hei ratonga, ā, ka āwhina te papa i a koe ki te whakahaere pai: ngā arowhai uptime, he whārangi tūnga tūmatanui, ngā aitua me tētahi pūrongo, ngā panonitanga me whai Haere, ngā kape tiaki ka tirotirohia ia rā. Ka ako te Āwhina i ia hipanga i a koe e haere ana.","msgr.h2":"AI-gile Messenger: tō rōpū i tō pūkoro","msgr.p1":"Kōrero ki tō rōpū AI me te kore e whakatuwhera i te papa. Kōrerorero ki ō kaiārahi kaupapa me ō hoa, tirohia ngā hipanga whakamātau o tētahi kāri ka whakautu ai, mai i tō waea katoa.","msgr.p2":"Hei hono, matawaitia tētahi waehere QR i tō papa. Te wā tuatahi? Mā tētahi kōrerorero whakaatu ngāwari koe e ārahi.","msgr.when":"Ko Android tuatahi, kātahi he putanga ipurangi mō ngā waea me te iPhone.","msgr.who":"Tō kaiārahi kaupapa","msgr.b1":"Kua rite te whakatika mō te aratau pōuri. Me tuku atu ngā hipanga whakamātau?","msgr.b2":"Āe rā, tēnā!","msgr.b3":"1. Whakatuwheratia ngā Tautuhinga. 2. Kōwhiria te Pōuri. He tika te āhua?","tl.aria":"Rārangi wā mai i te kōrero tuatahi ki te mahere","tl.h2":"Mai i te kōrero tuatahi ki te mea e haere ake nei","tl.lede":"He rā me ngā wā tūturu, i tō ake rohe wā. Whai muri i tēnei rā he mahere, kāore he rā i oatitia.","tl.today":"Tēnei rā","tl.planned":"kua whakaritea","tl.doing":"e mahi ana","tl.cards.one":"{n} kāri","tl.cards.other":"{n} kāri","join.h2":"Haere mai ki roto","join.lede":"Kei te hangaia a AI-gile e tētahi tangata pāhau rerekē, he AuDHD tōna, he pakanga anō ōna ki te hauora hinengaro, me te tini o ngā kaiwhakahaere manawanui. He tūmataiti i tēnei wā, i te alpha kati me ngā hoa. Kei te hiahia koe ki te whakamātau ina tuwhera?","join.btn":"Tohua tō aro","join.small":"Ka īmēra atu mātou, kāore atu","footer.tag":"AI-gile. Kāore he kaiwhai, kāore he pihikete, kāore he kawhe tū.","footer.licence":"Raihana pakihi","footer.status":"Tūnga","footer.privacy":"Ngā mea ka puritia e mātou","footer.thanks":"Ngā waea, he mihi ki a ChilledChat","form.sending":"E tuku ana…","form.failed":"Kāore i whai hua: whakamātauria anō a muri ake nei.","form.offline":"Kāore i taea te toro atu ki a AI-gile: whakamātauria anō a muri ake nei.","form.keep":"Ka whakamahia tēnei hei whakautu noa i a koe, kātahi ka mukua. Kāore he kaiwhai, kāore he pihikete.","form.keepLink":"Ngā mea ka puritia e mātou","interest.title":"AI-gile: whakamōhiotia mai ina tuwhera te alpha","interest.description":"Waihotia tō īmēra kia mōhio koe ina tuwhera te alpha kati, te beta rānei o AI-gile.","interest.h1":"🔔 Whakamōhio mai ina tuwhera","interest.lede":"Kei te pre-alpha kati a AI-gile. Waihotia tō īmēra, ā, ka tuhi atu mātou kotahi anake, ina whai wāhi koe.","interest.email":"Tō īmēra","interest.which":"Tēhea whakamātautau?","interest.alpha":"Alpha kati: tōmua, taratara, he maha ngā panoni","interest.beta":"Beta: kua pūmau ake, mō muri","interest.both":"Tētahi, ko tēhea te tuatahi","interest.submit":"Tāpiritia ahau ki te rārangi","interest.thanks":"Ngā mihi! Kei te rārangi koe.","licence.title":"AI-gile: raihana pakihi","licence.description":"E whakamahi ana i a AI-gile i tō pakihi? Tonoa he raihana pakihi koreutu.","licence.h1":"📜 Raihana pakihi","licence.lede":"E whakamahi ana i a AI-gile i te mahi? Kōrerotia mai ko wai koe, he aha tāu mahi. Mēnā he painga tāna, he koreutu te raihana.","licence.company":"Kamupene","licence.website":"Pae tukutuku","licence.what":"Tāu mahi","licence.how":"Tōna āwhina ki te ao","licence.email":"Īmēra","licence.submit":"Tono","licence.thanks":"Ngā mihi! Ka whakautu atu mātou mā te īmēra.","status.title":"Tūnga o AI-gile","status.h1":"Tūnga o AI-gile","status.quiet":"Kāore he raruraru","status.intro":"Kei te mahi a AI-gile i tēnei wā? Ka tirotirohia e tēnei whārangi te paetukutuku, te tiri papa, ngā waea me te tikiake ia 5 meneti.","status.up":"Kei te mahi (i whakautu i roto i te {ms} ms)","status.slow":"Kāore i whakautu ki te tirotiro whakamutunga, e whakamātau anō ana","status.down":"Kua hinga: kāore i whakautu ki ngā tirotiro whakamutunga e rua","status.svc.web":"Paetukutuku","status.svc.web.offers":"Tēnei pae: he aha a AI-gile, me te puka tohu aro","status.svc.boards":"Tiri papa","status.svc.boards.offers":"Ngā papa tūmatanui, ngā karere i waenga i ngā hoa, me ngā tono","status.svc.calls":"Ngā waea","status.svc.calls.offers":"Reo, ataata me te tiri mata i roto i a AI-gile","status.svc.download":"Tikiake","status.svc.download.offers":"Te kaitāuta Windows me ngā hono tono","status.checking":"E tirotiro ana…","status.offline":"Kāore e taea te toro ki te ratonga tūnga i tēnei wā (e whakamātau anō ana)","status.updated":"i whakahoutia {ago}","status.justNow":"inaianei tonu","status.min":"{n} meneti ki muri","status.hours":"{n} hāora ki muri","status.days":"{n} rā ki muri","privacy.title":"AI-gile: ngā mea ka puritia e mātou","privacy.h1":"Ngā mea ka puritia e mātou","privacy.lede":"Hei kōrero poto: ko ngā mea anake ka tukuna mai e koe, ā, mō te wā poto noa.","privacy.only":"Ko ngā mea anake ka tukuna mai e koe: ko ngā mea ka patoa e koe ki tētahi puka, pērā i tō īmēra. Kāore he mea kē atu mōu.","privacy.sealed":"Ka hiritia kia kore ai e taea e tō mātou tūmau te pānui: i roto i tō pūtirotiro i mua i tōna wehenga atu (i tētahi pūtirotiro tawhito, i te wā tonu ka tae mai). Ko tō mātou ake papa anake e taea ai te whakatuwhera.","privacy.server":"Ka mukua i te tūmau i te wā tonu ka tae ki tō mātou papa. Ko ngā mea kei reira tonu i muri i te 30 rā, ka mukua ahakoa te aha.","privacy.board":"Ka puritia e mātou ki tō mātou papa kia whakautu rā anō mātou ki a koe, kātahi ka mukua ki reira hoki.","privacy.none":"Kāore he kaiwhai, kāore he pihikete, kāore he tātari raraunga.","privacy.local":"Ko tō reo me tō kōwhiringa mārama, pōuri rānei ka noho tonu ki tō ake pūtirotiro. Kāore rawa e tukuna mai ki a mātou.","privacy.ask":"E hiahia ana kia mukua wawetia? Whakautua tā mātou īmēra, ka kī mai ai.","live.h2":"Matakitaki i tana hanganga, ora","live.caption":"Kua huna ia kāri katoa: ka kite koe i te āhua o te mahi, kaua ko ngā kupu.","live.watching.one":"ora: {n} e matakitaki ana","live.watching.other":"ora: {n} e matakitaki ana","live.last.now":"I nekehia te kāri whakamutunga inaianei tonu","live.last.min.one":"I nekehia te kāri whakamutunga {n} meneti kua pahure","live.last.min.other":"I nekehia te kāri whakamutunga {n} meneti kua pahure","live.last.hour.one":"I nekehia te kāri whakamutunga {n} haora kua pahure","live.last.hour.other":"I nekehia te kāri whakamutunga {n} haora kua pahure","live.last.day.one":"I nekehia te kāri whakamutunga {n} rā kua pahure","live.last.day.other":"I nekehia te kāri whakamutunga {n} rā kua pahure","live.offline":"Kei te okioki paku te papa ora. Hoki mai a muri nei.","live.cols":"Backlog|Hei mahi|E mahi ana|E arotakengia ana e te rōpū|Māu e test|Mā te rōpū|Oti"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Karetao.","Tukuna."]},{"n":2,"texts":["Kanban karetao.","Whakaaro, hangaia.","Mahi tukuna."]},{"n":3,"texts":["Kanban mō karetao.","Whakaaro hei āhuatanga.","Kanban kaiwhakahaere koreutu."]},{"n":5,"texts":["Papa kanban, ngā kaiwhakahaere hanga.","Tuhia ngā kāri. Hangaia e rātou.","Koreutu, ā-rorohiko, kua whakamātauria, āhua porangi."]},{"n":8,"texts":["He papa kanban koreutu e mahi ai ngā kaiwhakahaere AI.","Tuhia he whakaaro. Ka hangaia e ngā kaiwhakahaere. Whakaaetia.","Agile mō te tangata kotahi me te tini karetao manawanui."]},{"n":13,"texts":["He papa kanban i tō rorohiko e tango ai ngā kaiwhakahaere AI i ngā kāri.","Tuhia he whakaaro. Ka hangaia e tētahi rōpū kaiwhakahaere. Ka tirotirohia e tētahi kaiwhakamātau.","Kāore he kāute, kāore he kaiwhai: he papa, he karetao, ā, ko koe te rangatira."]},{"n":21,"texts":["He papa kanban a AI-gile hei mahi tahi ki ngā kaiwhakahaere waehere AI. Ka tango rātou i ngā kāri; mā koe e whakamātau, e whakaae.","He kaihautū me tētahi rōpū kaiwhakahaere AI tō ia kaupapa. Tāpiri kōrero ki tētahi kāri, ka tīmata te rōpū ki te mahi.","He papa mahi tūmataiti, koreutu, e rere ana i tō rorohiko. Ko ngā kaimahi he karetao. Ko koe te kaiwhakaae."]},{"n":34,"texts":["Ka whakatakotoria e koe ngā whakaaro ki te papa. Ka huria e tētahi rōpū kaiwhakahaere AI hei āhuatanga e mahi ana, ka whakamātauria, ka hoatu me ngā hikoi hei whakamātau. Kāore he mea e oti kia kore koe e kī.","He papa kanban i hangaia ā-ringa e Rich, me te āwhina nui a ngā kaiwhakahaere e whakahaerehia ana e ia inaianei. He koreutu, e rere ana i tō rorohiko, ā, ka tukua ki ngā hoa, ehara i te hoko.","Whakaarohia he papa kanban, he pou mai i te Backlog ki te Oti, engari ko ngā kaiwhakahaere AI ngā kaitango i ngā kāri. Ka kōrero rātou mō te ahunga whakamua, ka pātai ina piri, ā, ka tatari ki tō tohu pai."]},{"n":55,"texts":["He papa kanban a AI-gile e mahi ai ngā kaiwhakahaere AI hei rōpū. He kaihautū tō ia kaupapa hei whakamahere i te mahi, me ngā kaiāwhina hei hanga. Ina rite tētahi āhuatanga, ka whakamātauria e te kaiwhakamātau AI, ka tango tānga mata, ā, ka tae ki tō puranga. Whakaaetia, kōrerotia rānei, ā, ka mahi anō rātou.","I tīmata mai hei huarahi mā tētahi tangata ki te aroturuki i te maha o ngā wā mahi waehere AI i te wā kotahi, ā, i tupu hei papa tika. Ka rere i tō rorohiko, kāore he kāute e hiahiatia, kāore he kaiwhai. He koreutu mō ngā hoa me te hunga hihiri. Kāore anō kia oti, ka kitea ētahi tapa taratara me tētahi ohorere.","Anei te putanga pono. Māu tonu e whakaaro ngā whakaaro, māu tonu e tirotiro ngā putanga. Ko te mahi a AI-gile ko ngā mea katoa kei waenganui: ka tiaki i ngā kāri kia tōtika, ka whakaoho i te kaiwhakahaere tika ina kōrero koe, ka whakaatu he aha te mea kua rerekē, ka whakahaere i te katoa ki tētahi puranga poto mōu."]},{"n":89,"texts":["He papa kanban koreutu a AI-gile e rere ana i tō ake rorohiko. Hei utu mō ngā tāngata, he rōpū kaiwhakahaere AI tō ia kaupapa: he kaihautū hei huri i ō whakaaro hei kāri me tētahi mahere, me ngā kaiāwhina hei tango i ngā kāri i te raupapa matua. Ina oti tētahi mea te hanga, ka whai te kaiwhakamātau AI i ngā hikoi whakamātau, ka whakaatu i tāna i kite ai. Kātahi ka tatari ki roto i tētahi puranga e kīia ana Māu. Whakaaetia, kōrerotia rānei, ā, ka whakamātau anō te rōpū. Kāore he mea e tae ki Oti ki te kore koe.","Ētahi āhuatanga kāore pea koe e tūmanako. Ka whakakī te kaitiaki pō i te pou Hei mahi i a koe e moe ana, mā te kōwhiri i ngā kāri kāore e hiahia ana ki tō whakautu. Ka whakaatu te kaiwhakatatau tohu i te nui o tā ngā kaiwhakahaere whakamahi i tēnei rā, i tēnei wiki hoki. Ka taea e koe te tuku karere ki ngā hoa, ā, he hunahuna ngā karere tūmataiti mai i tētahi pito ki tētahi. E kōrero ana te papa i te 120 reo, tae atu ki te Tati, te kaipahua me te Klingon. Kāore tētahi o ēnei e utu moni.","He kaupapa iti, whaiaro a AI-gile, ehara i te kamupene. I hiahia a Rich ki te tiaki i ētahi kaupapa waehere AI me te kore e whakatuwhera i ia taupānga hei tirotiro, nā reira ka hangaia e ia me ngā kaiwhakahaere he papa mō tērā, ā, ka whakamahia taua papa ki te hanga i te toenga o ia ake. Kei te pre-alpha kati, arā, ka mahi, te nuinga o te wā, mō ētahi hoa torutoru. Kāore he whārangi utu, kāore he pānuitanga, kāore he mahere tipu. Mēnā he whai take, ka taea e koe te tono kia whakamātau ina tuwhera whānui ake."]},{"n":144,"texts":["He papa kanban a AI-gile mō tētahi tangata me te tini o ngā kaiwhakahaere AI. Ka rere i tō ake rorohiko, ā, he koreutu rawa. Ka kōrero koe ki te kaihautū, pērā i a Discord, ka whakaahua i tētahi whakaaro; ka huri te kaihautū hei kāri me tētahi mahere, ā, ka tatari kia pēhia e koe te Haere. Ka mahi te rōpū i ngā kāri i te raupapa matua, mā tētahi rārangi whakahau ngāwari i hangaia mō ngā tauira reo. I mua i te hokinga mai ki a koe, ka whai te kaiwhakamātau AI i ngā hikoi i runga i tētahi kape o te taupānga, ka tāpiri i tētahi tānga mata. Ka tae te mahi kua oti ki tō puranga me ngā kōnae kua rerekē me te rerekētanga. Ka whakaae koe, ka waiho rānei he kōrero, ā, ka oho te rōpū, ka whakamātau anō. Ko koe anake e taea te nuku i tētahi kāri ki Oti.","Anei te āhua o tētahi rā me AI-gile. I te ahiahi ka waiho e koe ētahi kōrero: kei te wāhi hē tēnei pātene, me whakarōpū tērā rārangi, me whai aratau pōuri pea. Ka haere koe ki te moe. Ka pānui ngā kaiwhakahaere i ngā kōrero, ka whakarerekē, ka whakamātau, ka hoatu anō ki a koe. Mēnā ka maroke te Hei mahi, ka whakakī te kaitiaki pō i a ia mai i te backlog ki ngā kāri kāore e hiahia ana ki tō whakautu. I te ata he puranga poto kotahi: tētahi rua pātai me ētahi mea hei whakamātau, tēnā me tēnā me ngā hikoi e taea e te tangata ngenge, me tētahi tānga mata e whakaatu ana kei te mahi. Ka pāwhiri koe, ka whakaae i ngā mea pai, ka whakahoki i te toenga. Ka whakaatu te kaiwhakatatau tohu i te nui o te pau, ā, kei reira te Aratau Kore Tohu mō ngā wiki kōmaki. Kātahi koe ka kai parakuihi, kāore anō kia taea e ngā kaiwhakahaere te āwhina.","Tuatahi, ehara a AI-gile i te aha. Ehara i te kamupene hōu, ehara i te mea e hokona ana, ā, kāore he tangata e kohi ana i ō raraunga. He papa koreutu e rere ana i tō rorohiko, kāore he kāute, kāore he kaiwhai, kāore he pihikete. Ko te mea ia: kotahi te wāhi tōtika hei tiro i ngā kaupapa waehere AI katoa i te wā kotahi, ko tētahi rōpū kaiwhakahaere e mahi ana i ngā kāri, ā, māu ngā whakatau. E kōrero ana i te 120 reo, mai i te Tati ki te kaipahua me te Klingon. I hangaia e Rich me te tini o ngā kaiwhakahaere manawanui, te nuinga mā te whakamahi i a ia ake. Kei te pre-alpha kati, nō reira he taratara ētahi wāhi. Mēnā he hākinakina, pātai atu i runga i te mihi, ā, tērā pea ka uru wawe koe."]}],"quips":{"1":"Kotahi te kupu. Pakari. Tērā pea he nui rawa te pakari.","3":"E toru ngā kupu. Kua pono ake i te nuinga o ngā whārangi hua.","8":"E waru ngā kupu. He poto tonu i tētahi stand-up.","21":"He tohu kōrero ngā roa, nā. Ae rā.","55":"E rima tekau mā rima ngā kupu. E rua ngā kāri i oti i a koe e pānui ana.","144":"Koinei te mea roa. Kāore he 233. Kua haere ngā kaiwhakahaere ki te moe."}},"timeline":{"first-idea.name":"Te whakaaro tuatahi","first-idea.line":"Te kōrero tuatahi rawa, i mua i te whai waehere.","first-board.name":"Te papa tuatahi","first-board.line":"He papa e whai ana i tōna ake hanga: ngā kāri, ngā pou, te toia, ngā kaupapa.","team-roles.name":"Te rōpū me ngā tūranga","team-roles.line":"Ngā kōtaha kaiwhakahaere, ngā tauira rōpū, ngā mokowā me te mahi a ia tangata.","install.name":"Te tāuta me ngā tukunga","install.line":"He zip e taea e tētahi hoa te tāuta, te whakahou-ā-tinana, ngā hongere me te hoki whakamuri.","usage-saver.name":"Te kaitiaki whakamahinga","usage-saver.line":"Ine i te utu o ngā whakahaerenga, kia kōmaki te waehere, kia mau tō tepe.","friends.name":"Ngā hoa me te tiritiri","friends.line":"Ngā karere tūmataiti, he hononga hunahuna, ngā pōwhiri, ngā tūranga me ngā kaupapa tiritahi.","languages.name":"Ngā reo","languages.line":"Ia kupu o ia mata i tētahi kōnae reo, ko te Tati tuatahi.","ai-tester.name":"Kaiwhakamātau AI","ai-tester.line":"Ka tirotiro tuatahi tētahi kaiwhakamātau i ia tukunga, ka whakaatu i tāna i kite ai.","website.name":"Te pae tukutuku","website.line":"aigile.lol, te whārangi tīmatanga me tēnei rārangi wā.","streaming.name":"Te kōrero me te rere ora","streaming.line":"Discord, Twitch, OBS, te aratau kaiwhakaatu, ngā GIF me ngā emoji.","no-ai.name":"Te putanga kore AI","no-ai.line":"He papa mō te hunga e waehere ana me te kore AI, me ngā papa tūmatanui.","night-watch.name":"Te kaitiaki pō","night-watch.line":"Ka whakahaere tētahi kaitiaki me tētahi Scrum Master i ngā rōpū i a koe e moe ana.","p-more.name":"Ngā mea katoa atu","p-more.line":"Ngā whakaaro iti e tatari tonu ana i tō rātou wā.","p-android.name":"Te waea me Android","p-android.line":"Toro atu ki tō papa mai i te waea, kātahi he taupānga Android ake.","p-release.name":"Te alpha me tua atu","p-release.line":"Te alpha kati, te pae ora, kātahi te beta.","p-languages.name":"Ētahi atu reo","p-languages.line":"130 ngā reo, me tētahi aratau rumaki mō ngā ākonga.","p-engines.name":"Ētahi atu pūkaha AI","p-engines.line":"Kōwhiria a Claude, Codex, Gemini, Copilot, Cursor rānei mō ia kaiwhakahaere.","p-pro.name":"Te tikanga ngaio","p-pro.line":"Ngā tūtohu tūpono, ngā kēti whakakotahi, ngā kāri aituā me ngā tiaki.","p-self.name":"Te tiaki i a koe","p-self.line":"Te aratau ngenge, ngā whakamahara tiaki-whaiaro me te 4:20.","p-servers.name":"Ngā tūmau me te whānui","p-servers.line":"Ngā tautuhinga tūmau ao, ngā tūranga me te whakamahere mō te tipu.","p-livestream.name":"Ngā taapiri rere ora","p-livestream.line":"Te kōrero Twitch, ngā emoji ake me tētahi tirohanga ora tūmatanui."},"words":{"button":"📖 Ngā kupu ngaio","h":"📖 Ngā kupu kua whakamāramatia","intro":"Ngā kupu ka tūtaki koe i roto i a AI-gile, i te reo māmā: te hanga, te panoni haumaru, te pupuri kia mahi tonu mō te hunga e whakamahi ana, me te mahi tahi hei rōpū me te AI.","search":"Rapua he kupu…","none":"Kāore he kupu e hāngai ana.","close":"Katia","count":{"one":"{count} kupu","other":"{count} kupu"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Te hanga"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Te panoni haumaru"},{"id":"run","name":"🛎️ Te whakahaere ratonga"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have.","also":["feasible"]},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["prioritising","prioritise","MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Ngā whakaaro me ngā mahi kāore anō kia whakamaherehia. Kāore he mea ki reira e mahia kia neke ki Hei mahi."},{"id":"sprint","g":"agile","word":"Sprint","text":"He wā poto o te mahi (te nuinga he wiki, e rua wiki rānei) me tētahi huinga kāri kua whakaaetia hei whakaoti.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"He tirotiro tere: i mahi ia mema rōpū i te aha, ka aha ā muri, he aha te mea e aukati ana i a ia.","also":["standup","stand-ups"]},{"id":"kanban","g":"agile","word":"Kanban","text":"He papa me ngā pou (Hei mahi, E mahi ana, Oti) e neke ai ngā kāri mai i te mauī ki te matau i te wā e mahia ana te mahi."},{"id":"wip","g":"agile","word":"WIP limit","text":"Mahi kei te haere: te nui rawa o ngā kāri hei pupuri e tētahi pou, kia whakaoti te rōpū i ngā mea i mua i te tīmata i ētahi atu.","also":["WIP"]},{"id":"dod","g":"agile","word":"Whakamārama o Oti","text":"Te rārangi-tirotiro poto a te rōpū mō te tikanga o “oti”, pēnei i te whakamātautia me te whakamāramatia, i mua i te tukunga o tētahi kāri ki a koe. Ko tōna māhanga, te Whakamārama o Rite, e kī ana āhea e mārama ai te kāri kia tīmata.","also":["Whakamārama o Rite","Definition of Done","Definition of Ready"]},{"id":"retro","g":"agile","word":"Retro","text":"He titiro whakamuri ki te āhua o te mahi a te rōpū, kia whakaae ki tētahi mea kotahi kia pai ake. I roto i a AI-gile ka tūtohu te retro i tētahi panonitanga ki ngā tikanga mahi a te rōpū, ā, ka kī koe Haere, Kāore anō rānei.","also":["arotake whakamuri","retros","retrospective"]},{"id":"swarm","g":"agile","word":"Kāhui","text":"Ringa katoa ki te mahi: ka waiho e ia rōpū ētahi atu mahi hei āwhina i tētahi kaupapa ohotata kia oti rā anō. Ka tatari ētahi atu kaupapa i taua wā.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Te tangata e pupuri ana kia rere tonu te mahi: ka kite i ngā kāri kua mau, ka akiaki i ngā rōpū, ka whakamaumahara i a koe ki ngā mea e tatari ana. I roto i a AI-gile ko te Lead Scrum Master e mahi ana i tēnei puta noa i ngā kaupapa katoa.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["SAFe","scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Te kōpaki waehere o te kaupapa me tōna hītori katoa o ngā commits, te nuinga e tiakina ana hoki ki GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"He rārangi mahi motuhake i te waehere, kia taea ai ngā panonitanga me te kore e pā ki te putanga matua.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"He hopu kua tiakina o te waehere, me tētahi tuhipoka poto mō te mea i panoni. Ka taea tonu te hoki ki tētahi.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Te tuku i ngā hopu kua tiakina (commits) mai i tēnei rorohiko ki GitHub, kia tiakina, kia tiri ai."},{"id":"merge","g":"build","word":"Merge","text":"Te whakahoki i ngā panonitanga o tētahi peka ki te putanga matua."},{"id":"pr","g":"build","word":"Pull request","text":"Te tono kia tirohia, kia whakakotahitia ngā panonitanga o tētahi peka ki te putanga matua.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Te whakapai i te waehere me te kore e panoni i tāna mahi: ngā kōpaki iti ake, ngā ingoa mārama ake, he iti ake te tuaruatanga."},{"id":"bug","g":"build","word":"Bug","text":"He mea kāore e mahi pērā i te tika.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Arotake a te hoa","text":"He karu tuarua: ka tirotirohia e tētahi AI kē te mahi o ia kāri i mua i tōna taenga ki a koe, kia iti iho ngā hapa ka puta.","also":["peer review","code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor.","also":["responsive"]},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiled","compiler","compiling"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Te whakamātau i tētahi mahi kua oti kia kite mēnā e mahi ana i te mea i tonoa, i mua i tō whakaae.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Poto mō quality assurance (whakaū kounga): ngā arowhai aunoa ka rere i mua i te haere ora o tētahi mea. Ki te whero te QA, kua hapa tētahi mea, ā, kāore e taea te haere ora kia whakatikahia rā anō.","also":["arowhai kounga","quality checks"]},{"id":"testpile","g":"test","word":"Puranga whakamātautau","text":"Ngā kāri kua oti e tatari ana kia whakamātauria e koe, tētahi i muri i tētahi. Whakaaetia tētahi, whakahokia rānei me tētahi tuhipoka, ā, ka puta mai te mea e whai ake ana.","also":["test pile"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["coverage","code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Te whakarewa i tētahi putanga hou kia ora, hei tauira ki tētahi tūmau e whakamahia ai e te tangata."},{"id":"release","g":"change","word":"Tukunga","text":"He paihere mahi kua oti, he ingoa tōna, ka haere ora tahi, me ngā kōrero poto mō ngā mea i panoni. Ka tuhia e 🚀 Tukunga ngā kōrero mai i ngā kāri kua oti.","also":["ngā tukunga","release","releases"]},{"id":"rollback","g":"change","word":"Huri whakamuri","text":"Te hoki ki te putanga whakamutunga i pai te mahi, ina raru te putanga hou. I roto i a AI-gile ka hanga tēnei i tētahi rārangi-tirotiro o ngā hipanga huri whakamuri kua tuhia ki ia panonitanga.","also":["whakahoki","rollback","roll back"]},{"id":"live","g":"change","word":"Haere ora","text":"Te putanga tūturu e whakamahia ana e te tangata, ehara i te kape hei whakamātau. E kīia ana hoki e ngā kaiwhakawhanake ko te production.","also":["live","production"],"noTip":1},{"id":"change","g":"change","word":"Panonitanga","text":"He panonitanga kua whakamaheretia ki tētahi mea e whakawhirinaki ana te tangata, kua tuhia i mua: he aha, he aha ai, te tūraru, āhea, me pēhea te huri whakamuri. Tīmatahia mā 🔀 Whakaara panonitanga.","also":["ngā panonitanga","tono panonitanga","huringa"],"noTip":1},{"id":"risk","g":"change","word":"Tūraru","text":"He mea ka hē pea, kua tohua he kaute mō te tūponotanga me te kino ka puta. Ka puritia e ⚠️ Ngā tūraru ki te rārangi kotahi, ko te kaute teitei rawa i mua, he rā tō ia mea kia tirohia anō.","also":["ngā tūraru","tūpono","rēhita tūraru"]},{"id":"chgwin","g":"change","word":"Matapihi panonitanga","text":"Ngā wā e āhei ai ngā panonitanga te haere ora, pēnei i tētahi ahiahi Tūrei mārie. I waho i te matapihi, kāore e taea te whakaoti i tētahi kāri panonitanga, ki te kore he ohotata.","also":["matapihi","ngā matapihi panonitanga"]},{"id":"gonogo","g":"change","word":"Haere / kaua e haere","text":"He pōti tere i mua tata i te haere ora o tētahi panonitanga: ka kī ia tangata me whakaae, Haere, Kaua e haere rānei. Ka haere whakamua anake ina whakaae rātou.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Whakaaetanga","text":"Te tatari ki tētahi āe i mua i te tīmatanga o te mahi. Ka tatari tētahi kāri nā tētahi hoa i whakaara, he panonitanga rānei, i ✅ Ngā whakaaetanga kia whakaae, kia whakakāhore rānei koe.","also":["ngā whakaaetanga"]},{"id":"quiettime","g":"change","word":"Wā ata noho","text":"He wā, pēnei i te pāho, te whakaaturanga, te pō rānei, kāore he mea e haere ora. Ka mahi tonu ngā rōpū, ka whakamātau tonu, engari ka tatari te haere ora kia mutu rā anō. I ētahi atu wāhi ka kīia he change freeze.","also":["ngā wā ata noho","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company.","also":["hosted"]},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Ratonga","text":"He mea nāu i hanga e whakawhirinaki ana te tangata, pēnei i te paetukutuku, i te taupānga rānei, e tiakina ana kia mahi tonu. Tīkina “He ratonga tēnei kaupapa”, ka kī ai he aha tāna e tuku ana, ko wai e whakamahi ana, ko wai kei te on-call.","also":["ngā ratonga","service"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Arowhai uptime","text":"He arowhai aunoa, ia meneti torutoru, kei te whakautu tonu tō ratonga. Ki te hapa i ētahi wā e hia nei i te rārangi, ka whakatuwhera a AI-gile i tētahi kāri aitua mā ōna anō.","also":["uptime","ngā arowhai uptime"]},{"id":"statuspage","g":"run","word":"Whārangi tūnga","text":"He whārangi tūmatanui e whakaatu ana mēnā kei te mahi tētahi ratonga (kākāriki, karaka, whero rānei) me te pānui hou rawa, kia taea e te hunga whakamahi te tirotiro, kaua e pātai.","also":["ngā whārangi tūnga","status page"]},{"id":"desk","g":"run","word":"Tēpu ratonga","text":"Te wāhi e tae mai ai ngā pātai me ngā pūrongo a te hunga e whakamahi ana i tō ratonga. Ka whakarōpūhia e AI-gile ia mea hei tono, hei aitua, hei whakaaro rānei, ā, ka kī mēnā he rite ki tētahi mea kua oti kē te pūrongo.","also":["ngā tēpu ratonga","tēpu āwhina","helpdesk"]},{"id":"svcrequest","g":"run","word":"Tono ratonga","text":"He tangata e tono ana i tētahi mea noa, pēnei i tētahi pūkete hou, i tētahi āwhina iti rānei, kaua ko te pūrongo kua pakaru tētahi mea. Ka tatari ki tōna wā; ko te aitua te tuatahi.","also":["ngā tono ratonga"]},{"id":"incident","g":"run","word":"Aitua","text":"He mea kua pakaru mō te hunga e whakamahi ana ināianei tonu, pēnei i te paetukutuku kua heke. Ka peke tētahi kāri 🔥 aitua i te rārangi: ko te whakahoki kia mahi anō te mea tuatahi.","also":["ngā aitua","incident"]},{"id":"major","g":"run","word":"Aitua nui","text":"He aitua nui: he tokomaha kua pāngia, he moni, he raraunga rānei kei te mōrearea. Ka whakanohoia e te pātene kotahi ngā rōpū katoa ki runga (kāhui), ka whakaohongia te tangata kei te on-call, ka tonoa he whakahou tūnga ia 30 meneti.","also":["ngā aitua nui","major incident"]},{"id":"oncall","g":"run","word":"On-call","text":"Ko koe te tangata ka whakautu ina pakaru tētahi mea, ahakoa i te pō. He mema rōpū on-call tō ia ratonga, ko ia te tuatahi ka whakaohongia mō ōna aitua.","also":["on call","kaimahi on-call"]},{"id":"replyby","g":"run","word":"Wā whakautu","text":"Te roa ka taea e tētahi kāri te tatari mō te whakautu tuatahi, hei tauira kotahi hāora mō tētahi aitua. I muri i tērā ka whiwhi karaka whero, kia kaua tētahi mea e wareware puku. Ka kīia hoki he whāinga whakautu.","also":["ngā wā whakautu","whāinga whakautu","response target"]},{"id":"postmortem","g":"run","word":"Arotake i muri i te aitua","text":"He titiro poto whakamuri i muri i tētahi aitua: te mea i pā, te mea i āwhina me te mea me panoni, me te kore whakahē i tētahi. Kāore e taea te kati i tētahi aitua mēnā kāore he arotake.","also":["post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Raruraru","text":"Te take huna kei muri i tētahi aitua, i ētahi aitua rānei. Ka whakarōpū tētahi kāri 🧩 raruraru i ngā aitua e hoki mai tonu ana, kia kitea ai te take, kia whakatikahia mō ake tonu.","also":["raru","ngā raruraru","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Pūtake tūturu","text":"Te take tūturu i pakaru ai tētahi mea, ehara i te mea i kitea e koe e hē ana anake. Whakatikahia te pūtake tūturu, ā, ka mutu te hoki mai o te aitua.","also":["ngā pūtake tūturu","root cause"]},{"id":"workaround","g":"run","word":"Aukati","text":"He huarahi e mahi tonu ai ngā mea kia rite rā anō te whakatika tūturu, pēnei i te tīmata anō i tētahi mea ina mau. Ka tuhia ki te kāri raruraru kia kaua tētahi e whakaaro anō.","also":["ngā aukati","rongoā mō te wā","workaround"]},{"id":"knownerror","g":"run","word":"Hapa e mōhiotia ana","text":"He raruraru kua mārama te take, he aukati tōna, engari kāore anō kia whakatikahia. Ka whakarārangitia e 🧩 Ngā hapa e mōhiotia ana, kia whakamahi te katoa i te aukati, kaua e keri anō.","also":["ngā hapa e mōhiotia ana","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"He tohutohu hipanga i te hipanga hei whakatika i tētahi momo raru e mōhiotia ana, kia ōrite te mahi, kia tere, i ia wā. I muri i tētahi aitua nui ka taea e te rōpū te tūtohu i tētahi mā tō OK.","also":["runbooks"]},{"id":"ci","g":"run","word":"Taonga whirihoranga","text":"He mea kotahi e whakawhirinaki ana tō ratonga ki runga, pēnei i te tūmau, te rohe, te tiwhikete, te kī, te kaiwhakarato rānei. Ka whakarārangitia e 🗂️ Ngā taonga whirihoranga mō ia ratonga, kia kite koe he aha e pāngia ana e tētahi aitua, he aha me whakahou, me kape tiaki rānei.","also":["ngā taonga whirihoranga"]},{"id":"expiry","g":"run","word":"Rā pau","text":"Ka mātakitaki a AI-gile i ngā rā pēnei i te wā ka pau tētahi tiwhikete, tētahi rohe rānei. I roto i ngā rā 30 i mua i taua rā ka hanga kotahi te kāri hei whakahou, kia kore ai tētahi mea e mutu ohorere.","also":["ngā rā pau","pau","tirotiro rā pau"]},{"id":"backup","g":"run","word":"Kape tiaki","text":"He kape kua tiakina o ō raraunga mai i mua, hei whakawhirinaki mēnā ka ngaro, ka pakaru rānei tētahi mea. Ka hanga a AI-gile i tētahi kape tiaki o ō papa ia rā.","also":["tiaki","ngā kape tiaki","backup"]},{"id":"restore","g":"run","word":"Whakahoki mai","text":"Te whakahoki mai i ngā raraunga i tētahi kape tiaki. Ka whai tikanga tūturu te kape tiaki ina mōhio koe ka taea te whakahoki mai, nō reira he pai te whakamātau i ētahi wā.","also":["whakahokia mai","restore"]},{"id":"svcreview","g":"run","word":"Arotake ratonga","text":"He titiro whakamuri ki te marama kotahi o tētahi ratonga: ngā aitua i tuwhera, i whakatikahia, te tere o te whakautu ki te tangata, te wā e mahi ana, me ngā tohu i whakamahia. Ka whakaaturia e te Arotake ā-marama mō ia ratonga.","also":["ngā arotake ratonga","arotake ā-marama","ngā arotake ā-marama"]},{"id":"accessreview","g":"run","word":"Arotake urunga","text":"Ia 90 rā ka tirohia ko wai e taea tonu te uru: ngā hono tiri, ngā tūranga o ngā hoa me ngā mea huna kua tiakina. Ka pupuri, ka tango rānei koe i ia mea, kia kore ai ngā urunga tawhito e toe noa iho.","also":["ngā arotake urunga"]},{"id":"improvements","g":"run","word":"Rārangi whakapainga","text":"Ngā mea katoa i whakatau te rōpū kia pai ake, i te wāhi kotahi: ngā whakaaro retro, ngā mahi arotake me ngā whakatika raruraru, me te tūnga o ia mea. Kei raro i 📈 Whakapainga.","also":["ngā rārangi whakapainga","whakapainga"]},{"id":"tokencap","g":"run","word":"Tepe tohu","text":"He tepe ā-marama mō ngā tohu e whakaaetia ana kia whakamahia e ngā kaiwhakahaere o tētahi ratonga. Ka tae ki te 80% ka whiwhi koe i tētahi whakatūpato; ka tae ki te 100% ka tatari ā rātou mahi o muri ki te marama e heke mai, kia whakapikia rānei e koe te tepe.","also":["ngā tepe tohu"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day.","also":["managing a service"]},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice.","also":["monitored"]},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing.","also":["lag"]},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first line","second line","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service.","also":["redundant"]},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers","hand over"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal.","also":["virus","viruses"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"He AI e mahi motuhake ana i tētahi mahi: ka pānui i te waehere, ka hanga panonitanga, ka whakahaere tirotiro, ka pūrongo mai.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"Te wae e tatauria ai te whakamahinga AI: tata ki ētahi pūrākau o te tuhinga kua pānuitia, kua tuhia rānei. Ko te iti ake o ngā tohu, ko te nui ake o tō mahere e toe ana.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"He whakahau iti e rere ana mā tōna ake i tētahi wā kua tohua, hei tauira ina tīmata tētahi nohoanga AI, kia rongo ai te rōpū i ō kōrero.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results.","also":["prompting"]},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals","evaluations"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers.","also":["purchasing"]},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
